hypotheses.statement:
The limit in <a href="#field:definition" data-reference-type="eqref" data-reference="field:definition">[field:definition]</a> exists locally uniformly, and $M_\delta:\mathop{\mathrm{Sym}}_n\to\mathop{\mathrm{Sym}}_n$ is locally Lipschitz. There is a $C^1$ function $J_\delta:\mathop{\mathrm{Sym}}_n\to\mathbb R$, normalized by $J_\delta(0)=0$, such that $$\label{field:primitive}
 dJ_\delta(B)[H]=-\mathop{\mathrm{tr}}(M_\delta(B)H).$$ The scalar function $\mu_\delta$ is locally Lipschitz and strictly increasing, with $\mu_\delta(0)=0$, and $$\label{field:mu-positive}
       \mu_\delta(z)=(z+\delta)^\sigma-\delta^\sigma
       \qquad(z\geq0).$$ For every real unit vector $e$, and for every standard basis vector $e_i$, respectively, $$\begin{aligned}
 e^{\mathsf T}M_\delta(B)e
  &\leq\mu_\delta\bigl(e^{\mathsf T}K^2e
                         -(e^{\mathsf T}Be)^2\bigr),
       \label{field:direction}\\
 Be_i=ye_i\quad&\Longrightarrow\quad
 M_\delta(B)e_i=\mu_\delta(k_i^2-y^2)e_i.
       \label{field:coordinate}
\end{aligned}$$ For each diagonal sign matrix $S$, $$\label{field:equivariance}
                 M_\delta(SBS)=SM_\delta(B)S.$$ Finally, $$\label{field:endpoints}
 \begin{split}
 J_\delta(-K)-J_\delta(K)
 &=\sum_{i=1}^n\int_{-k_i}^{k_i}\mu_\delta(k_i^2-s^2)\,ds\\
 &\longrightarrow b_\sigma\sum_{i=1}^n k_i^{2\sigma+1}
       \qquad(\delta\downarrow0).
 \end{split}$$

outputs.exact_statement:
For every $W$ satisfying <a href="#intro:class" data-reference-type="eqref" data-reference="intro:class">[intro:class]</a>, $$\label{intro:sharp}
 \mathop{\mathrm{Tr}}(H_W)_-^\gamma\le C_\gamma\int_\mathbb R\mathop{\mathrm{tr}}(W^p),
 \qquad
 C_\gamma=\left(\frac{\gamma-1/2}{\gamma+1/2}\right)^{\gamma-1/2}
       \frac{\Gamma(\gamma+1)}{\sqrt\pi\,\Gamma(\gamma+3/2)}.$$ Put $r=(\gamma-1/2)^{-1}$. Equality holds if and only if there are $k\in\{0,\ldots,m\}$, a constant unitary matrix $U$, positive numbers $a_1,\ldots,a_k$, and real numbers $x_1,\ldots,x_k$ such that almost everywhere $$\label{intro:classification}
 W(x)=U\mathop{\mathrm{diag}}\bigl(w_1(x),\ldots,w_k(x),0,\ldots,0\bigr)U^*,
 \quad
 w_j(x)=(r+1)a_j^2\mathop{\mathrm{sech}}^2\!\bigl(ra_j(x-x_j)\bigr).$$ The case $k=0$ means $W=0$. Each nonzero channel has exactly one negative eigenvalue, $-a_j^2$, and therefore every extremal potential has at most $m$ negative eigenvalues, counted with multiplicity.

For positive semidefinite matrices $W,Z$ of the same finite size, set $$\label{pre:young-defect}
 Y(W,Z)=D_\sigma\mathop{\mathrm{tr}}(W^p)-\mathop{\mathrm{tr}}(WZ)+\mathop{\mathrm{tr}}(Z^q).$$ Then $Y(W,Z)\ge0$, with equality if and only if $W=qZ^r$. Also, $$\label{pre:young-coercive}
 Y(W,Z)\ge\tfrac12\mathop{\mathrm{tr}}(Z^q)
       -(2^{p-1}-1)D_\sigma\mathop{\mathrm{tr}}(W^p).$$

Let $0<\sigma<1$ and $\kappa>0$. There is a constant $c_*=c_*(\sigma,\kappa)>0$ with the following property. For $n,d,\Omega,K$ as above, suppose $U\in H^1_0(\Omega;\mathbb R^{n\times d})$ satisfies $$\int_\Omega UU^{\mathsf T}\,dx=I_n.$$ For every $\eta>0$ there exist a real lower triangular matrix $C\in\mathbb R^{n\times n}$ and a path $B\in C^1(\overline\Omega;\mathop{\mathrm{Sym}}_n)$ such that $$B(x_-)=K,\qquad B(x_+)=-K,\qquad
 \sup_{x\in\overline\Omega}\|B(x)\|_{\mathop{\mathrm{op}}}\leq\kappa,$$ and, for $A=CU$, $$\label{act:bound}
 \mathcal E_K(A)\geq b_\sigma\sum_{i=1}^n\ell_i^{2\gamma}
   +\int_\Omega\left(\|A'-BA\|_{\mathrm{HS}}^2
                        +c_*\Phi_K(A,B)\right)\,dx-\eta.$$ In particular, $c_*$ is independent of $n,d,\Omega,U$, and the smallest diagonal entry of $K$.

The constant $c_*(\sigma,\kappa)>0$ can be chosen so that, whenever $0<\delta\leq1$, $\|B\|_{\mathop{\mathrm{op}}}\leq\kappa$, and $M_\delta(B)=AA^{\mathsf T}$, one has $$\label{act:constraint-bound}
 F(A,B)+c_*\Phi_K(A,B)\leq E_{n,\delta},
 \qquad
 E_{n,\delta}
 =n\bigl(\delta\kappa^{2\sigma}
           +\delta^\sigma(\kappa^2+\delta)\bigr)
      +\delta^{2\sigma}.$$

Let $n\geq1$ and let $B,V\in\mathbb C^{n\times n}$ be Hermitian. Suppose that $$\label{trace:symbol}
 Y_s=(sI-B)^2,\qquad X_s=Y_s+V\geq bI
 \quad(s\in\mathbb R)$$ for some $b>0$. Set $$\label{trace:resolvents}
 R(t)=\frac1\pi\int_\mathbb R(X_s+tI)^{-1}\,ds,
 \qquad P(t)=t^{-1/2}I-R(t),\qquad t>0,$$ and $$\label{trace:N}
 N=c_\sigma\int_0^\infty t^\beta P(t)\,dt.$$ These integrals converge absolutely in matrix norm, and $R(t)>0$. There are continuous Hermitian matrices $L(t)=R(t)^{-1}>0$ and $Z(t)$ satisfying $$\label{trace:LZ}
 V+tI=L^2+Z^2+i[B,Z],\qquad
 LZ+ZL+i[B,L]=0.$$ If $N\geq0$, then $$\label{trace:deficit-identity}
 \begin{split}
 \mathop{\mathrm{tr}}(NV)-\mathop{\mathrm{tr}}(N^q)
 =c_\sigma\int_0^\infty t^\beta\Bigl(
    \mathop{\mathrm{tr}}(RZ^2)
    +q\bigl\|R^{-1/2}-R^{1/2}(tI+N^r)^{1/2}\bigr\|_{\mathrm{HS}}^2
    \Bigr)\,dt.
 \end{split}$$ In particular, $\mathop{\mathrm{tr}}(NV)\geq\mathop{\mathrm{tr}}(N^q)$.

The limit in <a href="#field:definition" data-reference-type="eqref" data-reference="field:definition">[field:definition]</a> exists locally uniformly, and $M_\delta:\mathop{\mathrm{Sym}}_n\to\mathop{\mathrm{Sym}}_n$ is locally Lipschitz. There is a $C^1$ function $J_\delta:\mathop{\mathrm{Sym}}_n\to\mathbb R$, normalized by $J_\delta(0)=0$, such that $$\label{field:primitive}
 dJ_\delta(B)[H]=-\mathop{\mathrm{tr}}(M_\delta(B)H).$$ The scalar function $\mu_\delta$ is locally Lipschitz and strictly increasing, with $\mu_\delta(0)=0$, and $$\label{field:mu-positive}
       \mu_\delta(z)=(z+\delta)^\sigma-\delta^\sigma
       \qquad(z\geq0).$$ For every real unit vector $e$, and for every standard basis vector $e_i$, respectively, $$\begin{aligned}
 e^{\mathsf T}M_\delta(B)e
  &\leq\mu_\delta\bigl(e^{\mathsf T}K^2e
                         -(e^{\mathsf T}Be)^2\bigr),
       \label{field:direction}\\
 Be_i=ye_i\quad&\Longrightarrow\quad
 M_\delta(B)e_i=\mu_\delta(k_i^2-y^2)e_i.
       \label{field:coordinate}
\end{aligned}$$ For each diagonal sign matrix $S$, $$\label{field:equivariance}
                 M_\delta(SBS)=SM_\delta(B)S.$$ Finally, $$\label{field:endpoints}
 \begin{split}
 J_\delta(-K)-J_\delta(K)
 &=\sum_{i=1}^n\int_{-k_i}^{k_i}\mu_\delta(k_i^2-s^2)\,ds\\
 &\longrightarrow b_\sigma\sum_{i=1}^n k_i^{2\sigma+1}
       \qquad(\delta\downarrow0).
 \end{split}$$

If $M=M_\delta(B)\geq0$, then $$\label{field:positive-bounds}
 Q_s(B)\geq0\quad(s\in\mathbb R),\qquad
             0\leq M\leq\kappa^{2\sigma}I.$$ Set $V=K^2-B^2+\delta I$ and use $B,V$ in <a href="#trace:resolvents" data-reference-type="eqref" data-reference="trace:resolvents">[trace:resolvents]</a> and <a href="#trace:N" data-reference-type="eqref" data-reference="trace:N">[trace:N]</a>. Then the symbol $(sI-B)^2+V=Q_s(B)+\delta I$ is bounded below by $\delta I$, and $$\label{field:N}
                         N=M+\delta^\sigma I.$$ In particular, the hypotheses of Theorem <a href="#trace:deficit" data-reference-type="ref" data-reference="trace:deficit">10</a> hold.

hypotheses.statement:
The limit in <a href="#eq:field-M" data-reference-type="eqref" data-reference="eq:field-M">[eq:field-M]</a> exists locally uniformly on $\mathop{\mathrm{Sym}}_n$, and $M_\delta:\mathop{\mathrm{Sym}}_n\to\mathop{\mathrm{Sym}}_n$ is locally Lipschitz. There is a $C^1$ function $J_\delta:\mathop{\mathrm{Sym}}_n\to\mathbb R$, which we normalize by $J_\delta(0)=0$, such that $$\label{eq:field-primitive}
 dJ_\delta(B)[H]=-\mathop{\mathrm{tr}}(M_\delta(B)H)
       \qquad (B,H\in\mathop{\mathrm{Sym}}_n).$$

outputs.exact_statement:
For every $1/2<\gamma<3/2$, every finite $m\ge1$, and every $W$ satisfying <a href="#eq:potential-class" data-reference-type="eqref" data-reference="eq:potential-class">[eq:potential-class]</a>, $$\label{eq:main-bound}
 \mathop{\mathrm{Tr}}(H_W)_-^\gamma\le C_\gamma\int_\mathbb R\mathop{\mathrm{tr}}(W(x)^{\gamma+1/2})\,dx,
 \qquad
 C_\gamma=
 \left(\frac{\gamma-1/2}{\gamma+1/2}\right)^{\gamma-1/2}
 \frac{\Gamma(\gamma+1)}{\sqrt\pi\,\Gamma(\gamma+3/2)}.$$ The constant is optimal in every matrix dimension. With $r=(\gamma-1/2)^{-1}$, it is attained by $$\label{eq:extremal-potential}
 W(x)=\mathop{\mathrm{diag}}\big((r+1)\mathop{\mathrm{sech}}^2(rx),0,\ldots,0\big).$$

For every $0<\sigma<1$ and all the data just specified, $$\label{eq:action-bound}
 \sup_{C\in\mathcal L}\mathcal E(CU)
 \ge\sum_{i=1}^n\int_{-k_i}^{k_i}(k_i^2-s^2)^\sigma\,ds.$$

Let $n\geq1$ and let $B,V\in\mathbb C^{n\times n}$ be Hermitian. Suppose that for some $b>0$, $$\label{eq:trace-symbol}
 Y_s=(sI-B)^2,\qquad X_s=Y_s+V\geq bI
 \qquad\text{for every }s\in\mathbb R.$$ For $t>0$, set $$\label{eq:trace-resolvents}
 R(t)=\frac1\pi\int_\mathbb R(X_s+tI)^{-1}\,ds,
 \qquad P(t)=t^{-1/2}I-R(t),$$ and define $$\label{eq:trace-N}
 N=c_\sigma\int_0^\infty t^\beta P(t)\,dt.$$ These integrals converge absolutely in matrix norm. If $N\geq0$, then $$\label{eq:trace-comparison}
                         \mathop{\mathrm{tr}}(NV)\geq\mathop{\mathrm{tr}}(N^q).$$

For every $v\in\mathbb C^n$, equation <a href="#eq:trace-ode" data-reference-type="eqref" data-reference="eq:trace-ode">[eq:trace-ode]</a> has a unique $H^1$ solution on each half-line with boundary value $v$ at zero. There are Hermitian matrices $S=S(t)$ and $T=T(t)$ such that these solutions satisfy $$\label{eq:trace-boundary-maps}
 \nabla\psi(0+)=-Sv,\qquad \nabla\psi(0-)=Tv,$$ respectively. They obey $$\label{eq:trace-riccati}
 V+tI=S^2+i[B,S]=T^2-i[B,T],
 \qquad \frac{S+T}{2}=R(t)^{-1}.$$ Every eigenvalue of $B+iS$ has strictly positive imaginary part.

The limit in <a href="#eq:field-M" data-reference-type="eqref" data-reference="eq:field-M">[eq:field-M]</a> exists locally uniformly on $\mathop{\mathrm{Sym}}_n$, and $M_\delta:\mathop{\mathrm{Sym}}_n\to\mathop{\mathrm{Sym}}_n$ is locally Lipschitz. There is a $C^1$ function $J_\delta:\mathop{\mathrm{Sym}}_n\to\mathbb R$, which we normalize by $J_\delta(0)=0$, such that $$\label{eq:field-primitive}
 dJ_\delta(B)[H]=-\mathop{\mathrm{tr}}(M_\delta(B)H)
       \qquad (B,H\in\mathop{\mathrm{Sym}}_n).$$

For every $B\in\mathop{\mathrm{Sym}}_n$ and every real unit vector $e$, $$\label{eq:field-jensen}
 e^{\mathsf T}M_\delta(B)e
 \leq\mu_\delta\bigl(e^{\mathsf T}K^2e
                         -(e^{\mathsf T}Be)^2\bigr).$$ For a standard basis vector $e_i$ and $y\in\mathbb R$, $$\label{eq:field-coordinate}
 Be_i=ye_i\quad\Longrightarrow\quad
 M_\delta(B)e_i=\mu_\delta(k_i^2-y^2)e_i.$$ If $S$ is a diagonal matrix with diagonal entries in $\{1,-1\}$, then $$\label{eq:field-equivariance}
 M_\delta(SBS)=S M_\delta(B)S.$$ Finally, $$\label{eq:field-endpoints}
 J_\delta(-K)-J_\delta(K)
   =\sum_{i=1}^n\int_{-k_i}^{k_i}
                    \mu_\delta(k_i^2-s^2)\,ds.$$

For every $B\in\mathop{\mathrm{Sym}}_n$ such that $M_\delta(B)\geq0$, $$\label{eq:field-error}
 \mathop{\mathrm{tr}}\bigl(M_\delta(B)(K^2-B^2)\bigr)
       \geq\mathop{\mathrm{tr}}\bigl(M_\delta(B)^q\bigr)-E_\delta,
 \qquad
 E_\delta=n\bigl(\delta\kappa^{2\sigma}
                 +\delta^\sigma(\kappa^2+\delta)\bigr).$$ In particular, $E_\delta\to0$ as $\delta\downarrow0$ for fixed $K$.

Let $n,d\geq1$, let $\Omega=(x_-,x_+)$ be a bounded interval, and let $K=\operatorname{diag}(k_1,\ldots,k_n)$ with $k_i>0$. Suppose $U\in H^1_0(\Omega;\mathbb R^{n\times d})$ satisfies $$\int_\Omega UU^{\mathsf T}\,dx=I_n.$$ For every $\delta>0$ and $\varepsilon>0$, there are $C_\varepsilon\in\mathcal L$ and $B_\varepsilon\in C^1(\overline\Omega;\mathop{\mathrm{Sym}}_n)$ such that, with $A_\varepsilon=C_\varepsilon U$, $$\label{eq:path-ode}
    \varepsilon B_\varepsilon'
       =M_\delta(B_\varepsilon)-A_\varepsilon A_\varepsilon^{\mathsf T},
    \qquad
    B_\varepsilon(x_-)=K,
    \qquad B_\varepsilon(x_+)=-K.$$ These choices satisfy $$\label{eq:path-bounds}
    \sup_{x\in\overline\Omega}\|B_\varepsilon(x)\|_{\mathrm{op}}
       \leq\kappa,
    \qquad
    \sup_{0<\varepsilon\leq1}\|C_\varepsilon\|_{\mathrm{HS}}<\infty,$$ where the second bound is for fixed $\delta$, $K$, and $\Omega$.
